MERGE INTO SCM_ADM_API_M t USING (SELECT 'API_SCM0005_EXECUTE_QUERY' API_ID FROM DUAL) s ON (t.API_ID=s.API_ID)
 WHEN MATCHED THEN UPDATE SET API_TP_CD='POST', API_MSG_ID='MSG_API_SYS0013_RESULT_EXECUTE', API_URL='P_SCM0005_EXECUTE_QUERY', USE_YN='Y', LAST_UPDATED_BY='admin', LAST_UPDATE_DATE=SYSDATE
 WHEN NOT MATCHED THEN INSERT (API_ID, API_TP_CD, API_MSG_ID, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
   VALUES ('API_SCM0005_EXECUTE_QUERY','POST','MSG_API_SYS0013_RESULT_EXECUTE','P_SCM0005_EXECUTE_QUERY','Y','admin',SYSDATE,'admin',SYSDATE);
